import test from 'node:test';
import assert from 'node:assert/strict';
import {STORE_KEY} from '../dist/model.js';
test('new UI routes complete three subjects, show evidence and reviews, resume early review, isolate profile and preserve original practice',async()=>{
 const nodes=new Map();function node(key){if(!nodes.has(key))nodes.set(key,{innerHTML:'',textContent:'',events:{},dataset:{},focus(){},setAttribute(){},showModal(){this.open=true;},close(){this.open=false;},addEventListener(k,f){this.events[k]=f;},removeEventListener(){},querySelector(s){return node(key+' '+s);}});return nodes.get(key);}
 globalThis.document={body:{dataset:{}},querySelector:node,querySelectorAll:()=>[]};const map=new Map();globalThis.window={localStorage:{getItem:k=>map.get(k)??null,setItem:(k,v)=>map.set(k,v)},scrollTo(){},addEventListener(k,f){this[k]=f;}};let hash='';globalThis.location={get hash(){return hash;},set hash(v){hash=v?(v.startsWith('#')?v:'#'+v):'';}};globalThis.CSS={escape:x=>x};await import('../dist/app.js?loop-ui');
 const click=dataset=>node('#main').events.click({target:{closest:()=>({dataset,disabled:false})}}),route=h=>{location.hash=h;window.hashchange();},html=()=>node('#main').innerHTML,stored=()=>JSON.parse(map.get(STORE_KEY)),run=subject=>stored().profiles.A.learningLoop.runs.filter(r=>r.subject===subject).at(-1);
 const act=(subject,action,value)=>{const r=run(subject);click({loopAction:action,loopValue:value,loopRevision:String(r.revision),loopId:r.id});};
 assert.match(html(),/数学小步引导/);assert.match(html(),/本地复习安排/);
 for(const [subject,wrong,answer,transfer] of [['math','3','4','5'],['chinese','多','小','窄'],['english','an','a','an']]){route('#loop/'+subject);assert.equal(document.body.dataset.layout,'learning');act(subject,'select',wrong);assert.match(html(),/aria-pressed="true"/);act(subject,'submit');assert.match(html(),/引导 1 \/ 2/);const steps=subject==='math'?['每份的数量一样','每份数量 × 份数 = 总数']:subject==='chinese'?['题目描述的特点','放回两种情境，意思相反']:['后一个词开头的音素','an'];for(const v of steps){act(subject,'guide',v);assert.match(html(),/aria-pressed="true"/);act(subject,'next');}assert.match(html(),/引导后，再试原题/);act(subject,'select',answer);act(subject,'submit');assert.match(html(),/换一道同类新题/);act(subject,'select',transfer);act(subject,'submit');assert.match(html(),/把每一步分开看/);assert.equal(run(subject).answers[0].correct,false);assert.equal(run(subject).answers[2].correct,true);}
 route('#parent');assert.match(html(),/小步引导 · 按实际选择留证/);assert.match(html(),/首次独立选择/);assert.match(html(),/另一道同类题 · 独立选择/);route('#wrongs');assert.match(html(),/小步引导 · 原始未答对记录/);assert.match(html(),/原来选择：多/);
 route('#reviews');assert.match(html(),/将来到期/);click({loopReview:'math'});assert.match(html(),/提前练习/);act('math','select','3');act('math','submit');assert.match(html(),/提前复习/);const due=stored().profiles.A.learningLoop.reviews.math.due;route('#reviews');assert.match(html(),new RegExp(due));click({loopReview:'math'});assert.equal(run('math').phase,'initial');
 node('#profile-controls').events.click({target:{closest:()=>({dataset:{profile:'B'}})}});assert.match(html(),/暂无安排/);route('#loop/english');assert.match(html(),/先独立试一试/);assert.equal(stored().profiles.B.learningLoop.runs.length,1);assert.equal(stored().profiles.A.learningLoop.runs.length,5);
 route('#math');assert.match(html(),/12 颗糖/);assert.match(html(),/视频讲解/);route('#loop/constructor');assert.match(html(),/数学小步引导/);
});
